const r = $input.first().json;
const raw = Number(r.raw_jobs), dash = Number(r.dashboard_jobs), nat = Number(r.native_jobs);
if (!raw || dash !== raw || nat !== raw) {
  throw new Error(`Dashboard tables do not match instaleap_raw: raw ${raw} jobs, dashboard ${dash}, native ${nat}`);
}
return [{ json: { ok: true, ...r } }];
